const dcDoc=id=>((DC.list&&DC.list.docs)||[]).find(d=>d.id===id);
function dcProg(f){const p=$("#dcProg");p.hidden=f==null;if(f!=null)p.firstElementChild.style.width=Math.round(Math.max(0,Math.min(1,f))*100)+"%"}
